type State =
  | { status: 'idle' }
  | { status: 'uploading'; progress: number }
  | { status: 'done'; url: string }
  | { status: 'error'; message: string };

type Action =
  | { type: 'started' }
  | { type: 'progressed'; progress: number }
  | { type: 'finished'; url: string }
  | { type: 'failed'; message: string }
  | { type: 'reset' };

function uploadReducer(state: State, action: Action): State {
  switch (action.type) {
    case 'started':    return state.status === 'idle' ? { status: 'uploading', progress: 0 } : state;
    case 'progressed': return state.status === 'uploading' ? { ...state, progress: action.progress } : state;
    case 'finished':   return { status: 'done', url: action.url };
    case 'failed':     return { status: 'error', message: action.message };
    case 'reset':      return { status: 'idle' };
    default: { const _exhaustive: never = action; return state; }
  }
}

const [state, dispatch] = useReducer(uploadReducer, { status: 'idle' });

