function Thread({ messages, sendMessage }: { messages: Message[]; sendMessage: (text: string) => Promise<void> }) {
  const [optimisticMessages, addOptimistic] = useOptimistic(
    messages,
    (current, text: string) => [...current, { id: `temp-${current.length}`, text, sending: true }],
  );

  async function formAction(formData: FormData) {
    const text = String(formData.get('text'));
    addOptimistic(text);          // shown immediately
    await sendMessage(text);      // parent updates `messages` with server data
  }

  return (
    <>
      <ul>{optimisticMessages.map(m => <li key={m.id}>{m.text}{m.sending && ' (sending…)'}</li>)}</ul>
      <form action={formAction}><input name="text" /><button>Send</button></form>
    </>
  );
}

