function Carousel({ slides }: { slides: Slide[] }) {
  const [index, setIndex] = useState(0);

  const go = (dir: 'next' | 'prev') =>
    startTransition(() => {
      addTransitionType(dir);
      setIndex(i => (dir === 'next' ? i + 1 : i - 1 + slides.length) % slides.length);
    });

  return (
    <>
      <ViewTransition key={slides[index].id}
        enter={{ next: 'slide-from-right', prev: 'slide-from-left' }}
        exit={{ next: 'slide-to-left', prev: 'slide-to-right' }}>
        <SlideView slide={slides[index]} />
      </ViewTransition>
      <button onClick={() => go('prev')}>Prev</button>
      <button onClick={() => go('next')}>Next</button>
    </>
  );
}

