type CartState = {
  items: Record<string, { id: string; qty: number; price: number }>;
  add(id: string, price: number): void;
  remove(id: string): void;
};

export const useCart = create<CartState>()(
  devtools(persist(set => ({
    items: {},
    add: (id, price) => set(s => ({
      items: { ...s.items, [id]: { id, price, qty: (s.items[id]?.qty ?? 0) + 1 } },
    })),
