const filtersSchema = z.object({
  q: z.string().catch(''),
  status: z.enum(['all', 'open', 'closed']).catch('all'),
  page: z.coerce.number().int().min(1).catch(1),
});

export function useOrderFilters() {
  const [params, setParams] = useSearchParams();
  const filters = filtersSchema.parse(Object.fromEntries(params));

  const update = (patch: Partial<typeof filters>, opts?: { replace?: boolean }) =>
    setParams(prev => {
      const next = new URLSearchParams(prev);
      Object.entries({ ...patch, page: patch.page ?? 1 }).forEach(([k, v]) => next.set(k, String(v)));
      return next;
    }, opts);

  return [filters, update] as const;
}

