const RenameSchema = z.object({ projectId: z.string().uuid(), name: z.string().min(2).max(80) });

export async function renameProject(_prev: FormState, formData: FormData): Promise<FormState> {
  const session = await auth();
  if (!session) return { error: 'Please sign in.' };

  const parsed = RenameSchema.safeParse(Object.fromEntries(formData));
  if (!parsed.success) return { error: 'Invalid input.' };

  const project = await db.project.findUnique({ where: { id: parsed.data.projectId } });
  if (!project || project.ownerId !== session.userId) return { error: 'Not allowed.' };

  await db.project.update({ where: { id: project.id }, data: { name: parsed.data.name } });
  revalidatePath(`/projects/${project.id}`);
  return { ok: true };
}

