type SelectProps<T> = {
  label: string;
  options: readonly T[];
  value: T | null;
  getKey: (option: T) => string;
  getLabel: (option: T) => string;
  onChange: (option: T) => void;
} & Omit<ComponentPropsWithoutRef<'select'>, 'value' | 'onChange'>;

export function Select<T>({ label, options, value, getKey, getLabel, onChange, ...rest }: SelectProps<T>) {
  const id = useId();
  return (
    <>
      <label htmlFor={id}>{label}</label>
      <select
        id={id}
        value={value ? getKey(value) : ''}
        onChange={e => onChange(options.find(o => getKey(o) === e.target.value)!)}
        {...rest}
      >
        <option value="" disabled>Choose…</option>
        {options.map(o => <option key={getKey(o)} value={getKey(o)}>{getLabel(o)}</option>)}
      </select>
    </>
  );
}

