type LinkOrButtonProps =
  | ({ href: string } & ComponentPropsWithoutRef<'a'>)
  | ({ href?: undefined } & ComponentPropsWithoutRef<'button'>);

function Action(props: LinkOrButtonProps) {
  if (props.href !== undefined) return <a {...props} />;
  return <button type="button" {...props} />;
}

function TextField({ label, error, description, ...inputProps }: TextFieldProps) {
  const id = useId();
  const descId = `${id}-desc`;
  const errId = `${id}-err`;
  return (
    <div>
      <label htmlFor={id}>{label}</label>
      {description && <p id={descId}>{description}</p>}
      <input
        id={id}
        aria-invalid={!!error}
        aria-describedby={[description && descId, error && errId].filter(Boolean).join(' ') || undefined}
        {...inputProps}
      />
      {error && <p id={errId} role="alert">{error}</p>}
    </div>
  );
}
